use std::sync::{Arc,Mutex,atomic::{AtomicBool,AtomicU64,Ordering}};
#[derive(Default)]struct FakeCredentials{tokens:Mutex<std::collections::HashMap<String,String>>,fail_store:AtomicBool,load_delay:AtomicU64}
impl CredentialStore for FakeCredentials {
 fn store(&self,peer:&str,token:&str)->Result<(),String>{self.tokens.lock().unwrap().insert(peer.into(),token.into());if self.fail_store.load(Ordering::Relaxed){Err("Synthetic partially committed store failure".into())}else{Ok(())}}
 fn load(&self,peer:&str)->Result<String,String>{std::thread::sleep(std::time::Duration::from_millis(self.load_delay.load(Ordering::Relaxed)));self.tokens.lock().unwrap().get(peer).cloned().ok_or("Synthetic locked keyring".into())}
 fn clear(&self,peer:&str)->Result<(),String>{self.tokens.lock().unwrap().remove(peer);Ok(())}
}
async fn fixture()->(tempfile::TempDir,Arc<Storage>,Arc<Storage>,Arc<sync_service::SyncService>,Arc<PeerClient>,Arc<FakeCredentials>,String,String){
 let directory=tempfile::tempdir().unwrap();let hub=Arc::new(Storage::open(&directory.path().join("hub.sqlite")).await.unwrap());let local=Arc::new(Storage::open(&directory.path().join("peer.sqlite")).await.unwrap());let project=hub.create_project("Synthetic peer project").await.unwrap();let chapter=hub.create_chapter(&project.id,"Synthetic chapter").await.unwrap();let scene=hub.create_scene(&chapter.id,Scene{schema_version:1,title:"مِ 中文 😀".into(),document:json!({"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Synthetic عَ 世界 😀","marks":[{"type":"bold"}]}]}]})}).await.unwrap();let service=sync_service::SyncService::open(hub.clone(),directory.path().join("auth.json")).await.unwrap();let credentials=Arc::new(FakeCredentials::default());let client=PeerClient::open(local.clone(),directory.path().join("peer-clients.json"),credentials.clone()).unwrap();(directory,hub,local,service,client,credentials,project.id,scene.id)
}
async fn challenge(client:&PeerClient,service:&sync_service::SyncService,project:&str)->sync_service::PairingChallenge{let identity=client.identity().await.unwrap();service.create_pairing_challenge(sync_service::DeviceIdentity{device_id:identity["deviceId"].as_str().unwrap().into(),device_epoch:identity["deviceEpoch"].as_str().unwrap().into(),name:"Synthetic desktop".into()},vec![project.into()],60).await.unwrap()}
#[tokio::test]async fn actual_loopback_pair_sync_retry_reopen_conflicts_and_forget_keep_tokens_native(){
 let(directory,hub,local,service,client,credentials,project,scene)=fixture().await;let listener=service.start_listener("127.0.0.1:0".parse().unwrap()).await.unwrap();let endpoint=format!("http://{}",listener.address);assert_eq!(client.probe(&endpoint).await.unwrap()["transport"],"loopback-only");let approved=challenge(&client,&service,&project).await;let paired=client.pair(&endpoint,approved,&project).await.unwrap();let id=paired["peer"]["id"].as_str().unwrap();let token=credentials.tokens.lock().unwrap()[id].clone();assert!(!paired.to_string().contains(&token));assert!(!client.list().await.to_string().contains(&token));assert!(!std::fs::read_to_string(directory.path().join("peer-clients.json")).unwrap().contains(&token));let result=client.sync(id).await.unwrap();assert_eq!(result["morePending"],false);assert_eq!(result["assetsComplete"],true);assert_eq!(local.load_scene(&scene).await.unwrap(),hub.load_scene(&scene).await.unwrap());let before=local.sync_cursor().await.unwrap();client.sync(id).await.unwrap();assert_eq!(local.sync_cursor().await.unwrap(),before);
 let reopened=PeerClient::open(local.clone(),directory.path().join("peer-clients.json"),credentials.clone()).unwrap();assert_eq!(reopened.list().await["peers"][0]["id"],id);let original=local.load_scene(&scene).await.unwrap();let mut a=original.scene.clone();a.title="Local concurrent draft".into();local.save_scene(&scene,a,Some(original.revision_id.clone())).await.unwrap();let mut b=original.scene;b.title="Hub concurrent draft".into();hub.save_scene(&scene,b,Some(original.revision_id)).await.unwrap();reopened.sync(id).await.unwrap();assert!(!local.conflicts(&scene).await.unwrap().is_empty());assert!(!hub.conflicts(&scene).await.unwrap().is_empty());assert!(reopened.new_identity().await.is_err());let archive=local.export_archive(&project).await.unwrap();assert!(!archive.contains(&token));reopened.forget(id).await.unwrap();assert!(credentials.tokens.lock().unwrap().is_empty());assert!(reopened.list().await["peers"].as_array().unwrap().is_empty());let old_epoch=local.sync_cursor().await.unwrap().epoch;let old_identity=reopened.identity().await.unwrap()["deviceId"].clone();let new_identity=reopened.new_identity().await.unwrap();assert_ne!(old_identity,new_identity["deviceId"]);assert_eq!(new_identity["deviceEpoch"],old_epoch);listener.stop().await;
}
#[tokio::test]async fn failed_or_partial_keyring_store_is_cleared_without_plaintext_fallback(){let(directory,_hub,_local,service,client,credentials,project,_)=fixture().await;credentials.fail_store.store(true,Ordering::Relaxed);let listener=service.start_listener("127.0.0.1:0".parse().unwrap()).await.unwrap();let approved=challenge(&client,&service,&project).await;assert!(client.pair(&format!("http://{}",listener.address),approved,&project).await.unwrap_err().contains("was cleared"));assert!(credentials.tokens.lock().unwrap().is_empty());assert!(client.list().await["peers"].as_array().unwrap().is_empty());assert_eq!(std::fs::read_dir(directory.path()).unwrap().filter_map(Result::ok).filter(|entry|entry.file_name().to_string_lossy().contains("credential")).count(),0);listener.stop().await;}
#[tokio::test]async fn failed_metadata_commit_clears_the_already_stored_credential(){let(directory,_hub,_local,service,client,credentials,project,_)=fixture().await;let path=directory.path().join("peer-clients.json");std::fs::remove_file(&path).unwrap();std::fs::create_dir(&path).unwrap();let listener=service.start_listener("127.0.0.1:0".parse().unwrap()).await.unwrap();let approved=challenge(&client,&service,&project).await;assert!(client.pair(&format!("http://{}",listener.address),approved,&project).await.unwrap_err().contains("credential was cleared"));assert!(credentials.tokens.lock().unwrap().is_empty());listener.stop().await;}
#[tokio::test]async fn local_epoch_rotation_and_remote_revocation_fail_closed_without_resetting_cursors(){let(_directory,_hub,local,service,client,_credentials,project,_)=fixture().await;let listener=service.start_listener("127.0.0.1:0".parse().unwrap()).await.unwrap();let approved=challenge(&client,&service,&project).await;let device=approved.identity.device_id.clone();let paired=client.pair(&format!("http://{}",listener.address),approved,&project).await.unwrap();let id=paired["peer"]["id"].as_str().unwrap();let before=client.list().await;service.revoke_device(&device).await.unwrap();assert!(client.sync(id).await.unwrap_err().contains("revoked"));assert_eq!(client.list().await,before);local.rotate_epoch().await.unwrap();assert!(client.sync(id).await.unwrap_err().contains("local epoch changed"));assert_eq!(client.list().await,before);listener.stop().await;}
#[tokio::test(flavor="multi_thread",worker_threads=2)]async fn a_slow_keyring_worker_does_not_block_sqlite_acknowledgements(){let(_directory,_hub,local,service,client,credentials,project,scene)=fixture().await;let listener=service.start_listener("127.0.0.1:0".parse().unwrap()).await.unwrap();let approved=challenge(&client,&service,&project).await;let paired=client.pair(&format!("http://{}",listener.address),approved,&project).await.unwrap();let id=paired["peer"]["id"].as_str().unwrap().to_owned();client.sync(&id).await.unwrap();credentials.load_delay.store(400,Ordering::Relaxed);let running={let client=client.clone();tokio::spawn(async move{client.sync(&id).await})};tokio::time::sleep(std::time::Duration::from_millis(20)).await;let saved=local.load_scene(&scene).await.unwrap();let mut edited=saved.scene;edited.title="Saved while keyring waits".into();let started=std::time::Instant::now();local.save_scene(&scene,edited,Some(saved.revision_id)).await.unwrap();assert!(started.elapsed()<std::time::Duration::from_millis(200));assert!(!running.is_finished());running.await.unwrap().unwrap();listener.stop().await;}
#[tokio::test]async fn transport_rejects_remote_aliases_credentials_paths_and_queries_before_contact(){let(_directory,_hub,_local,_service,client,_credentials,_project,_scene)=fixture().await;for endpoint in ["https://100.64.1.2:443","http://100.64.1.2:17842","http://localhost:1234","http://127.1:1234","http://2130706433:1234","http://user:secret@127.0.0.1:1234","http://127.0.0.1:1234/path","http://127.0.0.1:1234?next=remote","http://[::1]:0"]{assert!(client.probe(endpoint).await.is_err(),"{endpoint}");}}
#[tokio::test]async fn unsupported_peer_metadata_with_credentials_is_rejected_without_blocking_writing(){let directory=tempfile::tempdir().unwrap();let path=directory.path().join("peer-clients.json");let value:Value=json!({"schemaVersion":1,"deviceId":"synthetic","peers":[],"token":"must-never-be-here"});std::fs::write(&path,value.to_string()).unwrap();#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;std::fs::set_permissions(&path,std::fs::Permissions::from_mode(0o600)).unwrap();}let storage=Arc::new(Storage::open(&directory.path().join("ordinary.sqlite")).await.unwrap());let result=PeerClient::open(storage.clone(),path.clone(),Arc::new(FakeCredentials::default()));assert!(result.is_err());assert_eq!(std::fs::read_to_string(&path).unwrap(),value.to_string());let project=storage.create_project("Writing remains available").await.unwrap();let chapter=storage.create_chapter(&project.id,"Chapter").await.unwrap();storage.create_scene(&chapter.id,Scene{schema_version:1,title:"مِ 中文".into(),document:json!({"type":"doc","content":[]})}).await.unwrap();assert_eq!(storage.open_project(&project.id).await.unwrap().scenes.len(),1);}
fn asset(id:&str,size:usize)->novel_storage::ProjectAsset{use sha2::{Digest,Sha256};let content=vec![b'x';size];novel_storage::ProjectAsset{id:id.into(),path:format!("assets/{id}.txt"),mime_type:"text/plain".into(),checksum:format!("{:x}",Sha256::digest(&content)),content}}
#[tokio::test]async fn large_asset_bytes_resume_in_both_directions_before_page_acknowledgement(){let(_directory,hub,local,service,client,_credentials,project,_)=fixture().await;hub.put_asset(&project,asset("synthetic-download",5*1024*1024)).await.unwrap();let listener=service.start_listener("127.0.0.1:0".parse().unwrap()).await.unwrap();let approved=challenge(&client,&service,&project).await;let paired=client.pair(&format!("http://{}",listener.address),approved,&project).await.unwrap();let id=paired["peer"]["id"].as_str().unwrap();let first=client.sync(id).await.unwrap();assert_eq!(first["assetsComplete"],false);assert_eq!(first["morePending"],true);assert_eq!(first["pendingAssets"][0]["direction"],"receive");assert_eq!(first["assetBytesTransferred"],4*1024*1024);assert!(local.list_assets(&project).await.unwrap().is_empty());let second=client.sync(id).await.unwrap();assert_eq!(second["assetsComplete"],true);assert_eq!(second["assetReceipts"],2,"Repeated immutable descriptors are checked once per direction in the pass.");assert_eq!(local.list_assets(&project).await.unwrap()[0],hub.list_assets(&project).await.unwrap()[0]);local.put_asset(&project,asset("synthetic-upload",5*1024*1024)).await.unwrap();let first_upload=client.sync(id).await.unwrap();assert_eq!(first_upload["assetsComplete"],false);assert_eq!(first_upload["pendingAssets"][0]["direction"],"send");let second_upload=client.sync(id).await.unwrap();assert_eq!(second_upload["assetsComplete"],true);let remote=hub.list_assets(&project).await.unwrap();let ours=local.list_assets(&project).await.unwrap();assert_eq!(remote,ours);listener.stop().await;}
#[tokio::test]async fn failed_cursor_publication_retries_received_pages_without_advancing_in_memory(){let(directory,_hub,local,service,client,_credentials,project,scene)=fixture().await;let listener=service.start_listener("127.0.0.1:0".parse().unwrap()).await.unwrap();let approved=challenge(&client,&service,&project).await;let paired=client.pair(&format!("http://{}",listener.address),approved,&project).await.unwrap();let id=paired["peer"]["id"].as_str().unwrap();let before=client.list().await;let path=directory.path().join("peer-clients.json");let old=std::fs::read(&path).unwrap();std::fs::remove_file(&path).unwrap();std::fs::create_dir(&path).unwrap();assert!(client.sync(id).await.unwrap_err().contains("metadata"));assert_eq!(client.list().await,before);let acknowledged=local.load_scene(&scene).await.unwrap();std::fs::remove_dir(&path).unwrap();std::fs::write(&path,old).unwrap();#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;std::fs::set_permissions(&path,std::fs::Permissions::from_mode(0o600)).unwrap();}client.sync(id).await.unwrap();assert_eq!(local.load_scene(&scene).await.unwrap(),acknowledged);listener.stop().await;}
#[tokio::test]async fn older_same_epoch_database_cannot_reuse_newer_metadata_after_partial_pull(){let(directory,hub,local,service,client,credentials,project,_)=fixture().await;let backup=directory.path().join("older.sqlite");local.backup(&backup).await.unwrap();for n in 0..40{hub.rename_project(&project,&format!("Synthetic revision {n}")).await.unwrap();}hub.put_asset(&project,asset("late-asset",5*1024*1024)).await.unwrap();let listener=service.start_listener("127.0.0.1:0".parse().unwrap()).await.unwrap();let approved=challenge(&client,&service,&project).await;let paired=client.pair(&format!("http://{}",listener.address),approved,&project).await.unwrap();let id=paired["peer"]["id"].as_str().unwrap();let result=client.sync(id).await.unwrap();assert_eq!(result["morePending"],true);let metadata=client.list().await;assert!(metadata["peers"][0]["pullSequence"].as_i64().unwrap()>0);assert_eq!(metadata["peers"][0]["pushSequence"],0);let old=Arc::new(Storage::open(&backup).await.unwrap());assert_eq!(old.sync_cursor().await.unwrap().epoch,local.sync_cursor().await.unwrap().epoch);let restored=PeerClient::open(old,directory.path().join("peer-clients.json"),credentials).unwrap();assert!(restored.sync(id).await.unwrap_err().contains("older backup"));assert_eq!(restored.list().await,metadata);listener.stop().await;}
#[tokio::test]async fn revision_page_ranges_reject_skips_repeats_and_wrong_epoch(){let(_directory,hub,_local,_service,_client,_credentials,project,_)=fixture().await;let epoch=hub.sync_cursor().await.unwrap().epoch;let valid=hub.pull_revisions(&project,novel_storage::SyncCursor{epoch:epoch.clone(),sequence:0},32).await.unwrap();peer_client::validate_revision_page(&valid,&epoch,0).unwrap();let mut invalid=valid.clone();invalid.revisions[0].sequence=0;assert!(peer_client::validate_revision_page(&invalid,&epoch,0).is_err());let mut invalid=valid.clone();invalid.has_more=true;invalid.next_sequence+=1;assert!(peer_client::validate_revision_page(&invalid,&epoch,0).is_err());assert!(peer_client::validate_revision_page(&valid,"wrong-epoch",0).is_err());let mut invalid=valid;invalid.revisions[1].sequence=invalid.revisions[0].sequence;assert!(peer_client::validate_revision_page(&invalid,&epoch,0).is_err());}
#[tokio::test]async fn backup_after_descriptor_before_asset_bytes_cannot_reuse_finalized_cursor(){let(directory,hub,local,service,client,credentials,project,_)=fixture().await;hub.put_asset(&project,asset("descriptor-before-bytes",5*1024*1024)).await.unwrap();let listener=service.start_listener("127.0.0.1:0".parse().unwrap()).await.unwrap();let approved=challenge(&client,&service,&project).await;let paired=client.pair(&format!("http://{}",listener.address),approved,&project).await.unwrap();let id=paired["peer"]["id"].as_str().unwrap();let first=client.sync(id).await.unwrap();assert_eq!(first["assetsComplete"],false);let backup=directory.path().join("descriptor-only.sqlite");local.backup(&backup).await.unwrap();let before_receipts=local.sync_receipt_count(&project,paired["peer"]["hubEpoch"].as_str().unwrap()).await.unwrap();let second=client.sync(id).await.unwrap();assert_eq!(second["assetsComplete"],true);let before=client.list().await;let old=Arc::new(Storage::open(&backup).await.unwrap());assert_eq!(old.sync_receipt_count(&project,paired["peer"]["hubEpoch"].as_str().unwrap()).await.unwrap(),before_receipts);assert!(old.list_assets(&project).await.unwrap().is_empty());let restored=PeerClient::open(old,directory.path().join("peer-clients.json"),credentials).unwrap();assert!(restored.sync(id).await.unwrap_err().contains("older backup"));assert_eq!(restored.list().await,before);listener.stop().await;}
#[tokio::test]async fn redirect_and_untrusted_error_messages_never_leak_remote_credential_text(){use tokio::io::{AsyncReadExt,AsyncWriteExt};for (code,body,extra) in [(302,"{}","Location: http://example.invalid/\r\n"),(401,"{\"ok\":false,\"error\":{\"code\":\"authentication\",\"message\":\"SYNTHETIC_BEARER_SECRET\"}}","")] {let(_directory,_hub,_local,_service,client,_credentials,_project,_scene)=fixture().await;let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let endpoint=format!("http://{}",listener.local_addr().unwrap());let server=tokio::spawn(async move{let(mut socket,_)=listener.accept().await.unwrap();let mut request=[0u8;1024];socket.read(&mut request).await.unwrap();let response=format!("HTTP/1.1 {code} Test\r\n{extra}Content-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",body.len());socket.write_all(response.as_bytes()).await.unwrap();});let error=client.probe(&endpoint).await.unwrap_err();assert!(!error.contains("SYNTHETIC_BEARER_SECRET"));assert!(error.contains(if code==302{"redirect"}else{"revoked"}));server.await.unwrap();}}
#[tokio::test]async fn duplicate_remote_tail_already_in_backup_cannot_hide_missing_received_writing(){let(directory,hub,local,service,client,credentials,project,scene)=fixture().await;let hub_epoch=hub.sync_cursor().await.unwrap().epoch;let local_epoch=local.sync_cursor().await.unwrap().epoch;let baseline=hub.pull_revisions(&project,novel_storage::SyncCursor{epoch:hub_epoch.clone(),sequence:0},1000).await.unwrap();local.ingest_revisions(&project,&local_epoch,&hub_epoch,hub.sync_manifest(&project).await.unwrap(),baseline.revisions).await.unwrap();let previous=local.sync_cursor().await.unwrap().sequence;let chapter=local.open_project(&project).await.unwrap().chapters[0].id.clone();let duplicate=local.create_scene(&chapter,Scene{schema_version:1,title:"Already in the old backup".into(),document:json!({"type":"doc","content":[]})}).await.unwrap();let old_snapshot=directory.path().join("contains-duplicate-tail.sqlite");local.backup(&old_snapshot).await.unwrap();let original=hub.load_scene(&scene).await.unwrap();let mut changed=original.scene;changed.title="New received writing absent from old backup".into();hub.save_scene(&scene,changed,Some(original.revision_id)).await.unwrap();let duplicates=local.pull_revisions(&project,novel_storage::SyncCursor{epoch:local_epoch.clone(),sequence:previous},1000).await.unwrap();hub.ingest_revisions(&project,&hub_epoch,&local_epoch,local.sync_manifest(&project).await.unwrap(),duplicates.revisions).await.unwrap();let listener=service.start_listener("127.0.0.1:0".parse().unwrap()).await.unwrap();let approved=challenge(&client,&service,&project).await;let paired=client.pair(&format!("http://{}",listener.address),approved,&project).await.unwrap();let id=paired["peer"]["id"].as_str().unwrap();client.sync(id).await.unwrap();let old=Arc::new(Storage::open(&old_snapshot).await.unwrap());let existing=old.load_entity_revision(&project,&duplicate.id,"scene",&duplicate.revision_id).await.unwrap();let path=directory.path().join("peer-clients.json");let mut metadata:Value=serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();metadata["peers"][0]["pullAnchor"]=json!({"id":existing.id,"entityId":existing.entity_id,"entityType":existing.entity_type,"checksum":existing.checksum});std::fs::write(&path,metadata.to_string()).unwrap();let restored=PeerClient::open(old.clone(),path,credentials).unwrap();assert_eq!(old.load_scene(&duplicate.id).await.unwrap().scene,duplicate.scene);let error=restored.sync(id).await.unwrap_err();assert!(error.contains("missing acknowledged peer receipts"),"{error}");assert_ne!(old.load_scene(&scene).await.unwrap().scene.title,local.load_scene(&scene).await.unwrap().scene.title);listener.stop().await;}

#[test]
fn tailscale_serve_candidates_are_strictly_scoped_without_enabling_unverified_https(){
    for endpoint in ["https://writer.tail123.ts.net","https://writer.tail123.ts.net/","https://writer.tail123.ts.net:443/"] {
        assert_eq!(peer_client::validate_tailscale_serve_endpoint(endpoint).unwrap().as_str(),"https://writer.tail123.ts.net/");
    }
    for endpoint in ["http://writer.tail123.ts.net","https://example.com","https://ts.net","https://writer.ts.net","https://a.b.c.ts.net","https://writer.tail123.ts.net.evil.test","https://-writer.tail123.ts.net","https://writer-.tail123.ts.net","https://writer..ts.net","https://Writer.tail123.ts.net","https://عربي.tail123.ts.net","https://writer%2e.tail123.ts.net","https://writer.tail123.ts.net:8443","https://secret@writer.tail123.ts.net","https://writer.tail123.ts.net/path","https://writer.tail123.ts.net//","https://writer.tail123.ts.net?token=secret","https://writer.tail123.ts.net#fragment","https://writer.tail123.ts.net\\evil.test","https://127.0.0.1:443"] {
        assert!(peer_client::validate_tailscale_serve_endpoint(endpoint).is_err(),"{endpoint}");
    }
}
#[test]
fn tailscale_dns_policy_rejects_empty_mixed_or_non_tailnet_addresses(){
    let parse=|text:&str|text.parse::<std::net::SocketAddr>().unwrap();
    assert!(peer_client::validate_tailscale_addresses(&[parse("100.64.0.0:443"),parse("100.127.255.255:443"),parse("[fd7a:115c:a1e0::1]:443")]).is_ok());
    for text in ["100.63.255.255:443","100.128.0.0:443","127.0.0.1:443","192.168.1.1:443","8.8.8.8:443","100.64.0.1:80","[fd7a:115c:a1df::1]:443","[fd7a:115c:a1e1::1]:443","[::ffff:100.64.0.1]:443","[::1]:443"]{
        assert!(peer_client::validate_tailscale_addresses(&[parse(text)]).is_err(),"{text}");
        assert!(peer_client::validate_tailscale_addresses(&[parse("100.64.0.1:443"),parse(text)]).is_err(),"mixed {text}");
    }
    assert!(peer_client::validate_tailscale_addresses(&[]).is_err());
    assert!(peer_client::validate_tailscale_addresses(&vec![parse("100.64.0.1:443");65]).is_err());
}
